package dev.veltraph.client.garden.jacob;

import dev.veltraph.client.config.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class JacobRewardJournalTest {
    private static final String HASH="a".repeat(64);
    private static JacobRewardJournal prepared(UUID id){return JacobRewardJournal.empty().prepare(id,"configured-wart-crops",HASH);}
    @Test void writeAheadIntentIsGloballyUnresolved(){var id=UUID.randomUUID();var j=prepared(id);assertEquals(id,j.pending().orElseThrow().id());assertFalse(j.canPrepare());assertThrows(IllegalStateException.class,()->j.prepare(UUID.randomUUID(),"other-configured-profile",HASH));}
    @Test void recreatedModuleOrConfigCannotLosePersistedPending(){var id=UUID.randomUUID();String file=prepared(id).encode();var first=JacobRewardJournal.decode(file);var afterConfigReset=JacobRewardJournal.decode(file);assertFalse(first.canPrepare());assertFalse(afterConfigReset.canPrepare());assertEquals(id,afterConfigReset.pending().orElseThrow().id());}
    @Test void unknownSurvivesRestartWithoutAutomaticRetry(){var id=UUID.randomUUID();var j=JacobRewardJournal.decode(prepared(id).unknown(id).encode());assertEquals(JacobRewardJournal.Phase.UNKNOWN,j.pending().orElseThrow().phase());assertFalse(j.canPrepare());assertThrows(IllegalStateException.class,()->j.prepare(UUID.randomUUID(),"configured-wart-crops",HASH));}
    @Test void explicitAppliedDecisionIsNotNativeReceiptCredit(){var id=UUID.randomUUID();var j=prepared(id).unknown(id).reconcile(id,HASH,JacobRewardJournal.Decision.APPLIED);var e=j.entries().getFirst();assertTrue(j.canPrepare());assertEquals(JacobRewardJournal.Phase.RECONCILED_APPLIED,e.phase());assertNull(e.receiptId());assertThrows(IllegalStateException.class,()->j.acknowledge(id,UUID.randomUUID()));}
    @Test void explicitNotAppliedDecisionDoesNotAdoptOldUnknown(){var id=UUID.randomUUID();var j=prepared(id).reconcile(id,HASH,JacobRewardJournal.Decision.NOT_APPLIED);assertNull(j.entries().getFirst().receiptId());assertEquals(JacobRewardJournal.Phase.RECONCILED_NOT_APPLIED,j.entries().getFirst().phase());assertThrows(IllegalStateException.class,()->j.unknown(id));}
    @Test void wrongIntentOrContractCannotReconcile(){var id=UUID.randomUUID();var j=prepared(id);assertThrows(IllegalStateException.class,()->j.reconcile(UUID.randomUUID(),HASH,JacobRewardJournal.Decision.APPLIED));assertThrows(IllegalArgumentException.class,()->j.reconcile(id,"b".repeat(64),JacobRewardJournal.Decision.APPLIED));assertFalse(j.canPrepare());}
    @Test void nativeAcknowledgmentStoresExactSeparateReceiptId(){var id=UUID.randomUUID();var actual=UUID.randomUUID();var j=prepared(id).acknowledge(id,actual);assertEquals(actual,j.entries().getFirst().receiptId());assertEquals(JacobRewardJournal.Phase.ACKNOWLEDGED,j.entries().getFirst().phase());assertTrue(j.canPrepare());}
    @Test void retentionNeverEvictsUnknownOrConfirmedHistory(){var j=JacobRewardJournal.empty();for(int i=0;i<63;i++){var id=UUID.randomUUID();j=j.prepare(id,"local",HASH).acknowledge(id,UUID.randomUUID());}var unknown=UUID.randomUUID();j=j.prepare(unknown,"local",HASH).unknown(unknown);var full=j;assertEquals(64,full.entries().size());assertThrows(IllegalStateException.class,()->full.prepare(UUID.randomUUID(),"local",HASH));assertEquals(unknown,full.pending().orElseThrow().id());var settled=full.reconcile(unknown,HASH,JacobRewardJournal.Decision.NOT_APPLIED);assertFalse(settled.canPrepare());assertEquals(64,settled.entries().size());}
    @Test void corruptUnsupportedAmbiguousOrDuplicateDataRefuses(){for(String bad:List.of("","{}","null","{\"schema\":1,\"generation\":0,\"entries\":[]}","{\"schema\":2,\"generation\":0,\"entries\":[]}"))if(!bad.equals(JacobRewardJournal.empty().encode()))assertThrows(RuntimeException.class,()->JacobRewardJournal.decode(bad));var j=prepared(UUID.randomUUID());var raw=j.encode();assertThrows(RuntimeException.class,()->JacobRewardJournal.decode(raw.replace("\"entries\":", "\"entries\":[],\"entries\":")));assertThrows(RuntimeException.class,()->JacobRewardJournal.decode(raw.replace("\"UNRESOLVED\"","\"UNSUPPORTED\"")));assertThrows(RuntimeException.class,()->JacobRewardJournal.decode(" "+raw));}
    @Test void malformedSchemaAndGenerationNeverNormalizeToEmpty(){String empty=JacobRewardJournal.empty().encode();assertThrows(RuntimeException.class,()->JacobRewardJournal.decode(empty.replace("\"schema\":1","\"schema\":1.5")));assertThrows(RuntimeException.class,()->JacobRewardJournal.decode(empty.replace("\"generation\":0","\"generation\":\"0\"")));assertThrows(RuntimeException.class,()->JacobRewardJournal.decode(empty.replace("\"generation\":0","\"generation\":-1")));}
    @Test void settledIntentCannotBeReused(){var id=UUID.randomUUID();var j=prepared(id).acknowledge(id,UUID.randomUUID());assertThrows(IllegalStateException.class,()->j.prepare(id,"local",HASH));}
    @Test void knownBackingDetectsConfigAbaAndForeignReplacement(){var config=new MapConfigService();var key=ConfigKey.ofBool("PRIVATE_JACOB_ABA",false);var fence=JacobRewardJournalConfigFence.capture(config).orElseThrow();config.set(key,true);config.set(key,false);assertFalse(fence.current(config));assertFalse(fence.current(new MapConfigService()));}
}
